import{_ as o,c as d,a0 as t,o as c}from"./chunks/framework.B6JXc2q-.js";const _=JSON.parse('{"title":"ADR-0008：每台设备一个播放版本号","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0008-playback-version.md","filePath":"adr/0008-playback-version.md"}'),a={name:"adr/0008-playback-version.md"};function r(i,e,n,l,s,h){return c(),d("div",null,e[0]||(e[0]=[t('<h1 id="adr-0008-每台设备一个播放版本号" tabindex="-1">ADR-0008：每台设备一个播放版本号 <a class="header-anchor" href="#adr-0008-每台设备一个播放版本号" aria-label="Permalink to &quot;ADR-0008：每台设备一个播放版本号&quot;">​</a></h1><ul><li><strong>状态</strong>：Accepted（2026-11-23 Akari 认可；按“实施步骤”分步落地）</li><li><strong>日期</strong>：2026-11-23</li><li><strong>关联</strong>：ADR-0007 第 6 步（“把 sid / LifecycleToken / 手动切歌代际 / barrier 收敛为每个队列的版本号”）</li></ul><h2 id="上下文" tabindex="-1">上下文 <a class="header-anchor" href="#上下文" aria-label="Permalink to &quot;上下文&quot;">​</a></h2><p>播放流程里几乎每一步都要回答同一个问题：“我手上这件事是不是已经过时了？”（用户又按了别的、队列已经换了、播放已经停了）。现在用五套计数器分别回答：</p><table tabindex="0"><thead><tr><th>计数器</th><th>什么时候前进</th><th>谁在检查</th></tr></thead><tbody><tr><td><code>sid</code>（<code>_play_session_id</code>）</td><td><code>_playmusic</code> 开始、API 点播、停止</td><td>计时器、后台任务、拉流事件；也是网关地址里的队列号</td></tr><tr><td><code>q</code>（<code>queue_session_id</code>）</td><td>只有 API 点播</td><td>严格检查、屏障检查</td></tr><tr><td><code>c</code>（<code>command_generation</code>）</td><td>每个受理的命令（播放、停止、上下首、API 点播、<strong>自动切歌、失败重试</strong>）</td><td>严格检查、命令执行前</td></tr><tr><td><code>a</code>（<code>track_attempt_id</code>）</td><td>每次实际下发（<code>_playmusic</code>、API 点播执行器）</td><td>严格检查、屏障检查、下发返回后</td></tr><tr><td>切歌代际（<code>_manual_nav_generation</code>）</td><td>用户命令和手动上下首（<strong>不含</strong>自动切歌、重试）</td><td><code>_playmusic</code> 和下发的各个阶段</td></tr></tbody></table><p>另有两种组合判断：严格检查 = <code>q</code>、<code>c</code>、<code>a</code> 全等；屏障检查 = <code>sid</code>、<code>q</code>、<code>a</code>，特意不看 <code>c</code>（否则停止后排队的命令会把正在执行的停止判成过期）。</p><p>代价：</p><ol><li><strong>难读、难改</strong>：同一段代码里常常要连查三次（<code>sid</code>、token、切歌代际），漏查一处就是一个竞态。源码里约 230 处、测试里约 500 处引用。</li><li><strong>语义不一致留下的隐患</strong>：用户命令受理后，旧队列在命令真正开始执行前仍被当作“当前队列”跟随；arbiter 对普通命令又是“后到的替换排队中的”，理论上旧窗口的哨兵或本地切歌产生的 AUTO_NEXT 能顶掉用户排队中的命令。 <ul><li><strong>更正（2026-11-23，动手写复现测试时重新推演）</strong>：现状下这几乎不可能发生。命令一开始执行，<code>_playmusic</code> 就推进 <code>sid</code>，旧队列随即失效；即便 AUTO_NEXT 先挤进去，它执行前的严格 token 检查也会因为用户命令推进了 <code>a</code> 而把它丢弃；剩下的只有“已受理、执行协程尚未运行”的毫秒级窗口，且跟随任务开头还会再查一次。起草时说成“1～2 s 的竞态”是夸大了。</li><li>但第 3 步删掉 <code>(q, c, a)</code> 严格检查后，这些碰巧生效的保护就没有了，所以下面第 2 节的两条规则仍然需要，作为合并计数器的前提。</li></ul></li></ol><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><h3 id="_1-一个版本号" tabindex="-1">1. 一个版本号 <a class="header-anchor" href="#_1-一个版本号" aria-label="Permalink to &quot;1. 一个版本号&quot;">​</a></h3><p>每台设备只有一个整数 <code>version</code>，<strong>在命令开始执行时前进</strong>（arbiter 工作协程取出命令后，执行任何物理操作之前）：PLAY、NEXT、PREVIOUS、AUTO_NEXT、RETRY、STOP 都前进一次。</p><ul><li>所有异步延续（计时器、开播确认、跟随、失败重试的等待、下发返回后的收尾）在创建时记下 <code>version</code>，执行前比较，不等即丢弃。</li><li>网关地址里的队列号就是下发时的 <code>version</code>；拉流事件的队列号不等于当前 <code>version</code> 即为旧队列。</li><li>一次命令执行内的多次下发（API 点播的备用地址）共用同一个 <code>version</code>，不再需要 <code>a</code>。</li><li>停止是唯一的屏障。停止执行器只检查自己开始时的 <code>version</code> 有没有被另一个<strong>停止</strong>改变；排队在停止之后的命令不会让它过期，因为它们要等停止执行完才开始执行、才前进 <code>version</code>。因此不再需要“特意不看 <code>c</code>”的屏障检查。</li></ul><h3 id="_2-受理与执行分开" tabindex="-1">2. 受理与执行分开 <a class="header-anchor" href="#_2-受理与执行分开" aria-label="Permalink to &quot;2. 受理与执行分开&quot;">​</a></h3><ul><li><strong>受理</strong>（API 返回之前，同步）：只做校验、更新给 WebUI 看的“目标曲目”、把命令交给 arbiter。受理不前进 <code>version</code>。</li><li><strong>用户命令一受理，当前队列即标记为“已被取代”</strong>：跟随逻辑不再处理它的拉流事件（不跟随、不因哨兵续接、不因过期重发），只记日志。这一条直接消除上面的竞态。</li><li><strong>arbiter 的优先级</strong>：用户命令（PLAY / NEXT / PREVIOUS / STOP）可以替换排队中的任何命令；自动命令（AUTO_NEXT / RETRY）<strong>不能</strong>替换排队中或正在执行的用户命令，遇到时直接丢弃并记日志。</li></ul><h3 id="_3-删除" tabindex="-1">3. 删除 <a class="header-anchor" href="#_3-删除" aria-label="Permalink to &quot;3. 删除&quot;">​</a></h3><p><code>q</code>（并入 <code>version</code>）、<code>c</code>、<code>a</code>、切歌代际、<code>LifecycleToken</code>（换成一个 <code>int</code>）、屏障检查、<code>navigation_generation</code> 参数。<code>TaskGeneration</code> 改为只用 <code>version</code>。</p><h3 id="_4-行为变化-相对现状" tabindex="-1">4. 行为变化（相对现状） <a class="header-anchor" href="#_4-行为变化-相对现状" aria-label="Permalink to &quot;4. 行为变化（相对现状）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>现在</th><th>之后</th></tr></thead><tbody><tr><td>手动下一首受理后、执行前，旧窗口哨兵被拉取</td><td>AUTO_NEXT 可能顶掉用户的“下一首”</td><td>旧队列已被取代，不产生 AUTO_NEXT；用户的“下一首”照常执行</td></tr><tr><td>自动切歌正在执行时用户按下一首</td><td>用户的命令排队，自动切歌执行完后再执行</td><td>不变（用户命令替换排队中的、不打断正在执行的；执行中的自动切歌在下一个检查点因 <code>version</code> 前进而停止）</td></tr><tr><td>停止后紧接着播放</td><td>播放排在停止之后</td><td>不变</td></tr><tr><td>API 点播的备用地址</td><td>第二次下发会让第一次的收尾判为过期</td><td>共用一个 <code>version</code>；收尾只在最后一次下发后进行，结果相同</td></tr></tbody></table><p>其余行为不变。</p><h2 id="实施步骤" tabindex="-1">实施步骤 <a class="header-anchor" href="#实施步骤" aria-label="Permalink to &quot;实施步骤&quot;">​</a></h2><p>每一步都先补行为测试（fake 音箱 + 真网关，见 <code>tests/behavior/</code>），全量测试通过，测试服实机验证后再推送。</p><ol><li>✅ <strong>受理即取代 + arbiter 优先级</strong>（2026-11-23）：用户命令受理时把当前窗口标记为“已被取代”（<code>_supersede_queue</code>，挂在 <code>_invalidate_manual_navigation</code> 和手动上下首的受理上），跟随逻辑忽略它的拉流事件；AUTO_NEXT / RETRY 在有用户命令排队（含排在停止之后）时被拒绝（<code>IntentReceipt.accepted=False</code>），但用户命令<strong>执行中</strong>仍可提交（失败策略在 PLAY 执行过程中提交 RETRY）。单元测试覆盖规则与接线（撤掉实现时全部失败）。</li><li><strong>切歌代际 → <code>version</code></strong>：手动上下首改为记录执行时的 <code>version</code>，删除 <code>_manual_nav_generation</code> 和 <code>navigation_generation</code> 参数。</li><li><strong><code>sid</code>、<code>q</code> 合并为 <code>version</code>，删除 <code>a</code>、<code>c</code>、<code>LifecycleToken</code>、屏障检查</strong>。这一步会删掉大量绑定 <code>(q, c, a)</code> 的单元测试，事先用行为测试覆盖它们保护的场景（停止期间的各种命令、执行中的取消、过期的后台任务）。</li><li><strong>mixin 改为对象组合</strong>（ADR-0007 第 6 步剩余部分）：DevicePlayer 持有 SpeakerQueue、PlaybackFollower 等对象，各自只通过 <code>version</code> 判断过期。</li></ol><h2 id="修订-2026-11-23-实施第-2-步时" tabindex="-1">修订（2026-11-23，实施第 2 步时） <a class="header-anchor" href="#修订-2026-11-23-实施第-2-步时" aria-label="Permalink to &quot;修订（2026-11-23，实施第 2 步时）&quot;">​</a></h2><p>动手后发现第 1 节“版本号在命令开始执行时前进”与现有、且被测试锁定的行为冲突，第 3 步“<code>sid</code> 并入 <code>version</code>”也不成立。修订如下（实现以本节为准）：</p><ol><li><strong>受理即前进</strong>：连按三次“下一首”时，第一次正卡在慢速停止里，后两次在此期间受理；现状是第一次在下一个检查点放弃，只下发最后的目标（<code>test_rapid_next_presses_dispatch_only_the_final_target</code>，单首与队列两条路径都有）。只在执行开始时前进的版本号做不到这一点。所以“当前命令”仍由<strong>受理时前进</strong>的命令代际 <code>c</code> 判断。第 2 步已据此把手动切歌代际换成 <code>c</code>（✅ 2026-11-23）。</li><li><strong><code>sid</code> 不是 <code>c</code> 的重复</strong>：<code>c</code> 回答“哪个命令是当前的”（受理时前进）；<code>sid</code> 回答“音箱上是哪一批内容”（开始下发、停止、API 点播时前进），是网关地址里的队列号。失败重试、兜底计时器、拉流跟随都是“记下 <code>sid</code> → 提交自动命令 → 稍后确认仍是这批内容”；若 <code>sid</code> 换成 <code>c</code>，它们会在提交自己的命令后把自己判为过期（失败重试会失效）。逐处核对的 30 个使用位置都属于“内容”语义。</li><li><strong>新终点：两个计数器</strong>——命令代际 <code>c</code>（受理）与队列号 <code>sid</code>（下发）。删除 <code>q</code>（只在 API 点播时前进，且总与 <code>sid</code> 同时前进）和 <code>a</code>（一次命令内的多次下发只发生在 API 点播的备用地址，且是同一协程里顺序进行），<code>LifecycleToken</code> 收缩为 <code>(c, sid)</code>，屏障检查改为只看 <code>sid</code>。</li><li><strong>“已被取代”标记</strong>（第 1 步）保留：它补上的是“<code>c</code> 已前进、<code>sid</code> 尚未前进”的那段时间。</li></ol><p>剩余工作（删除 <code>q</code>、<code>a</code>，收缩 <code>LifecycleToken</code>）会改写约 220 处绑定 <code>(q, c, a)</code> 的旧单元测试，先等 Akari 确认修订后的方向再做。</p><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><ul><li>正面：过期判断只有一种写法；竞态的来源（受理和执行混在一起、旧队列仍被跟随）被消除；第 3 步预计再删一千多行代码和测试。</li><li>负面：第 3 步改动面大，期间要依赖行为测试而不是旧的单元测试来保证正确；需要在测试服做较长时间的实机播放验证。</li></ul><h2 id="待确认" tabindex="-1">待确认 <a class="header-anchor" href="#待确认" aria-label="Permalink to &quot;待确认&quot;">​</a></h2><ol><li>第 2 节“自动命令不能替换用户命令”是否符合预期？（例如：用户刚点了一首歌、还没开播，此时旧队列的计时器到点——之后不会再切到旧歌单的下一首。）</li><li>是否同意按 1 → 4 的顺序分步做？第 1 步可以先单独做，不依赖其余部分。</li></ol>',30)]))}const u=o(a,[["render",r]]);export{_ as __pageData,u as default};
